  // The home page (app/HomeClient.tsx); ML-DSA-65, ML-KEM-768, X25519, TLS 1.3, QUIC, NIST FIPS 203 and 204 are names
  home_live_blocks: 'Live-Blöcke',
  home_deck: 'Eine experimentelle Blockchain, von einer einzigen Person entworfen und mit KI-Unterstützung gebaut',
  home_hero_p: 'Keine Finanzierung. Kein Team. Kein Unternehmen im Rücken. Die Architektur und jede Protokollentscheidung stammen von einer Person; der Code wird unter dieser Leitung mit KI-Werkzeugen geschrieben.',
  home_open_explorer: 'Explorer öffnen',
  home_tps: 'Überweisungen/s',
  home_tps_sub: 'Durchgängig gemessen in einem Testnet mit 5 Knoten; 40,000–80,000 auf Validator-Hardware',
  home_epoch_label: 'Eine vierstündige Epoche eines Light-Knotens: Statusanfragen, jede mit einer Signatur beantwortet, und eine signierte Bestätigung dazwischen',
  home_epoch_title: 'Eine Epoche · 4 Stunden',
  home_hours: '{h} h',
  home_epoch_key_request: 'Eine Statusanfrage von QNet Blockchain, mit einer Signatur beantwortet',
  home_epoch_key_attestation: 'Eine signierte Bestätigung pro Epoche, zwischen den Anfragen',
  home_eco_title: 'Wirtschaftsmodell',
  home_eco_lead: 'Zwei Aktivierungsphasen und zwei Belohnungspools',
  home_phase_current: 'Aktuell',
  home_phase_future: 'Künftig',
  home_phase: 'Phase {n}',
  home_phase1_title: '1DEV-Verbrennung',
  home_phase1_body: '1DEV-Token werden für die Knotenaktivierung auf Solana verbrannt: 1,500 1DEV für jeden Knotentyp, und der Betrag sinkt, je mehr von der Menge verbrannt ist. Die Token werden vernichtet, und niemand erhält sie. Die Knoten von QNet Blockchain prüfen die Verbrennungstransaktion selbst: keine Brücke und keine verpackten Token.',
  home_phase2_title: 'QNC an Pool #3',
  home_phase2_when: 'Beginnt, wenn 90% der ursprünglichen 1DEV-Menge verbrannt sind oder fünf Jahre nach dem Genesis-Block, je nachdem, was zuerst eintritt.',
  home_phase2_body: 'Die Aktivierung verbraucht QNC, die an Pool #3 gehen und an alle aktiven Knoten umverteilt werden. Der Betrag richtet sich nach der Netzwerkgröße; der genaue Plan wird festgelegt, bevor Phase 2 beginnt.',
  home_halving_title: 'Halving mit steilem Abfall',
  home_halving_label: 'Basisemission pro Jahr auf logarithmischer Skala: alle 4 Jahre halbiert bis Jahr 20, durch 10 geteilt für die Jahre 20 bis 24, dann wieder alle 4 Jahre halbiert',
  home_halving_unit: 'Basisemission, log. Skala',
  home_halving_years: 'Jahre',
  home_halving_caption: 'Jahre 0–20: ÷2 alle 4 Jahre. Jahre 20–24: ein steiler Abfall, ÷10. Ab Jahr 24 setzt das Halving von der niedrigen Basis aus wieder ein.',
  home_mult_title: 'Aktivierungsbetrag nach Netzwerkgröße',
  home_mult_1: '0–100,000 Knoten',
  home_mult_2: '100,000–300,000 Knoten',
  home_mult_3: '300,000–1,000,000 Knoten',
  home_mult_4: '1,000,000+ Knoten',
  home_mult_caption: 'Multiplikator auf den Aktivierungsbetrag in Phase 2. Jede Aktivierung in Phase 2 geht an Pool #3.',
  home_pools_title: 'Zwei Belohnungspools',
  home_pools_1: 'Basisemission nach dem Halving-Plan, in jeder Epoche unter den als online erfassten Knoten aufgeteilt.',
  home_pools_2: 'Pool #3, gespeist aus den Aktivierungen der Phase 2 und unter allen aktiven Knoten geteilt.',
  home_pools_fees: 'Transaktionsgebühren gehen an den Erzeuger des Blocks.',
  home_security_title: 'Sicherheitsmodell',
  home_pq_title: 'Post-Quanten-Kryptografie',
  home_pq_body: 'Signaturen sind ausschließlich ML-DSA-65 (NIST FIPS 204), auf jeder Transaktion und jeder Konsensnachricht, für Wallets, Knoten und Konsens gleichermaßen. Knoten kommunizieren über TLS 1.3 auf QUIC mit einem hybriden Schlüsselaustausch aus X25519 + ML-KEM-768 (FIPS 203), authentifiziert mit ML-DSA-65.',
  home_rep_datum: 'Gleiche Knoten, bewiesene Verstöße',
  home_rep_title: 'Reputationsbasierte Sicherheit',
  home_rep_body: 'Keine Token-Sperre, kein Einziehen von Guthaben. Erzeuger und Komitees werden durch überprüfbaren Zufall aus allen berechtigten Knoten gezogen. Ein Knoten, der zwei widersprüchliche Blöcke signiert, wird auf der Chain überführt und von jeder künftigen Ziehung ausgeschlossen; alle anderen behalten volle Liquidität und ein gleiches Stimmrecht.',
  home_rate_datum: 'Limits pro IP',
  home_rate_title: 'Ratenbegrenzung',
  home_rate_body: 'Die öffentliche API jedes Knotens begrenzt jede IP-Adresse (eine IPv6-Adresse nach ihrem /64): 100 Transaktionseinreichungen und 300 Lesezugriffe pro Minute sowie 5 Aktivierungen pro Stunde, mit einer Pause nach Überschreiten eines Limits. Eingehende Transaktionen werden in einem separaten, begrenzten Prüfpool geprüft, und die Blockvalidierung hat ihren eigenen Pool.',
  home_mobile_title: 'Eine Blockchain für das Telefon',
  home_mobile_lead: 'Eine Blockchain für Telefone: Teilnahme ist eine signierte Antwort, kein Proof-of-Work',
  home_presence_title: 'Präsenz statt Proof-of-Work',
  home_presence_body: 'Ein Light-Knoten beantwortet einige Male pro vierstündiger Epoche eine signierte Statusanfrage von QNet Blockchain. Zwischen den Anfragen sendet die App nur eine signierte Bestätigung pro Epoche. Kein Hashing und kein Proof-of-Work: Jede Antwort ist eine einzige Signatur, daher leistet das Telefon keine Dauerarbeit.',
  home_app_title: 'Eine App auf jedem Telefon und Tablet',
  home_app_body: 'Dieselbe App und dieselben Bildschirme auf iPhone, iPad sowie Android-Telefonen und -Tablets: stille Push-Weckrufe für Statusanfragen und Entsperren mit Face ID, Touch ID, Fingerabdruck oder Gerätecode, oder mit einem App-Passwort auf einem Gerät ohne diese.',
  home_app_stores: 'Jetzt bei {play}; auf iPhone und iPad im {appStore}.',
  home_app_stores_testflight: 'Jetzt bei {play}; auf iPhone und iPad über {testflight}, bis der Eintrag im App Store live ist.',
  home_app_languages: 'In 11 Sprachen:',
  home_hw_title: 'Hardwaregestützte Sicherheit',
  home_hw_body: 'Post-Quanten-Schlüssel sind im Ruhezustand verschlüsselt und durch den Schlüsselspeicher des Systems geschützt. Ein Light-Knoten ist über einen Schlüssel in der sicheren Hardware an ein Gerät gebunden: Ein Gerät betreibt einen Knoten, und Computer und Emulatoren betreiben keinen.',
  home_split_title: 'Wie die Emission aufgeteilt wird',
  home_split_body: 'Für jede Epoche erfasst QNet Blockchain, welche Knoten online waren. Das Protokoll fügt ihrem Knotenguthaben einen Anteil an der Emission dieser Epoche hinzu (drei Viertel unter Light-Knoten, ein Viertel unter Super-Knoten), und die Wallet überträgt ihn mit einer gewöhnlichen Transaktion zu sich.',
  home_split_label: 'Drei Viertel der Emission jeder Epoche an Light-Knoten, ein Viertel an Super-Knoten',
  home_super_nodes: 'Super-Knoten',
  home_source_title: '100% Open-Source-Code',
  home_source_lead: 'Diese Website verwendet genau denselben Code, der auf GitHub veröffentlicht ist.',
  home_source_licenses: 'Die Wallet-Apps und der Explorer sind unter Apache-2.0 veröffentlicht, der Knoten unter der Business Source License 1.1.',
  home_source_check: 'Quellcode prüfen',
  home_source_verify: 'Build verifizieren',


  // The DAO page (app/dao)
  dao_title: 'DAO von QNet Blockchain',
  dao_lead: 'Auf QNet Blockchain läuft noch keine Governance, daher listet diese Seite keine Vorschläge und nimmt keine Abstimmungen an.',
  dao_changes_title: 'Wie sich das Protokoll heute ändert',
  dao_changes_p1: 'Eine Protokolländerung wird mit einer Version der Knotensoftware ausgeliefert, in die die Blockhöhe geschrieben ist, ab der sie gilt. Jeder Knoten, der diese Version betreibt, wendet die Änderung bei dieser Höhe an, daher ist keine Abstimmung auf der Chain nötig, um sich darauf zu einigen.',
  dao_changes_p2: 'Die {guide} beschreibt, wie ein Knoten eine neue Version übernimmt; die {docs} enthält den Rest.',
  dao_guide_link: 'Wartungsanleitung',
  dao_docs_link: 'Dokumentation',
  dao_design_title: 'Entwurfsmaterial',
  dao_design_p: 'Der Entwurf des Governance-Vertrags und seine Werkzeuge für Vorschläge liegen im {folder} des Repositorys. Nichts davon ist auf QNet Blockchain bereitgestellt.',
  dao_folder_link: 'Governance-Ordner',


